BEGIN;

-- Pinned public SVRS domains, retrieved 10/11/2026. No external lookup occurs
-- during model saves. Full official flags/validities are retained, not inferred.
CREATE TABLE private.nfse_fiscal_catalog_releases (
  id text PRIMARY KEY,provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object')
);
CREATE TABLE private.nfse_fiscal_classifications (
  code text PRIMARY KEY CHECK(code ~ '^[0-9]{6}$'),
  cst text NOT NULL CHECK(cst ~ '^[0-9]{3}$' AND left(code,3)=cst),
  definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'
    AND definition->>'classificationCode'=code AND definition->>'cst'=cst),
  release_id text NOT NULL REFERENCES private.nfse_fiscal_catalog_releases(id)
);
CREATE TABLE private.nfse_fiscal_credits (
  code text PRIMARY KEY CHECK(code ~ '^[0-9]{2}$'),
  definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object' AND definition->>'code'=code),
  release_id text NOT NULL REFERENCES private.nfse_fiscal_catalog_releases(id)
);
ALTER TABLE private.nfse_fiscal_catalog_releases ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.nfse_fiscal_classifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.nfse_fiscal_credits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.nfse_fiscal_catalog_releases,private.nfse_fiscal_classifications,
  private.nfse_fiscal_credits FROM PUBLIC,anon,authenticated,service_role;
